  .test-head h2 { margin: 0 0 8px; font-size: clamp(21px, 2.6vw, 27px); letter-spacing: -.02em; }
  .test-head p { margin: 0; color: var(--muted); font-size: 14.5px; line-height: 1.55; }
  .test-head p + p { margin-top: 5px; }
  .test-head strong { color: var(--ink); font-weight: 700; }
  .tabs-wrap { padding: 15px 20px 0; border-bottom: 1px solid var(--line); background: #fff; }
  .tabs {
    display: flex; gap: 8px; overflow-x: auto; scrollbar-width: thin;
    padding: 0 2px 14px;
  }
  .tab {
    flex: 0 0 auto;
    border: 1px solid var(--line);
    background: #fbfcff;
    color: var(--muted);
    border-radius: 999px;
