    font-size: 13px; font-weight: 700;
    cursor: pointer;
    transition: background .18s, border-color .18s, color .18s, transform .18s;
  }
  .tab:hover { border-color: #cbd6ee; color: var(--ink); transform: translateY(-1px); }
  .tab.is-active {
    color: #fff; border-color: transparent;
