    box-shadow: 0 8px 22px rgba(40, 58, 105, .045);
  }
  .disc-card__title, .disc-card__foot {
    color: var(--muted);
    font-size: 11.5px; font-weight: 800;
    letter-spacing: .1em; text-transform: uppercase;
  }
  .disc-card__title { margin: 0 2px 10px; color: var(--brand); }
  .disc-card__foot { margin: 10px 2px 1px; text-align: right; color: #98a1b5; }
  .disc-list {
    list-style: none; margin: 0; padding: 0;
    display: flex; flex-direction: column; gap: 9px;
    counter-reset: rank;
  }
  .disc-item {
    position: relative;
    display: flex; align-items: center; gap: 10px;
    min-height: 48px;
    padding: 10px 10px 10px 12px;
    border: 1px solid #e5eaf5;
    border-radius: 13px;
    background: #fff;
    box-shadow: 0 3px 9px rgba(38, 56, 103, .045);
    font-size: 14px; line-height: 1.25;
    cursor: grab;
    user-select: none; -webkit-user-select: none;
    touch-action: manipulation;
    transition: border-color .16s, box-shadow .16s, background .16s, opacity .16s, transform .16s;
    counter-increment: rank;
    outline: none;
  }
  .disc-item::before {
    content: counter(rank);
    width: 23px; height: 23px; flex: 0 0 auto;
    display: grid; place-items: center;
    border-radius: 50%;
    background: var(--brand-soft);
    color: var(--brand);
    font-size: 11px; font-weight: 800;
  }
  .disc-item:hover {
    border-color: #b9c8ef;
    box-shadow: 0 7px 18px rgba(59, 91, 219, .11);
    transform: translateY(-1px);
  }
  .disc-item:focus-visible { border-color: var(--brand); box-shadow: 0 0 0 3px rgba(59, 91, 219, .16); }
  .disc-item .item-text { flex: 1 1 auto; min-width: 0; }
  .drag-handle {
    width: 27px; height: 27px; flex: 0 0 auto;
    display: grid; place-items: center;
    border-radius: 8px;
    color: #a8b2c8;
    background: #f4f6fb;
    touch-action: none;
    cursor: grab;
  }
  .drag-handle svg { width: 15px; height: 15px; display: block; }
  .disc-item.is-placeholder {
    opacity: .32;
    background: var(--brand-soft);
    border-style: dashed;
    border-color: #9fb2ea;
    box-shadow: none;
    transform: none;
  }
  .disc-item.is-placeholder::before { background: #dbe3ff; }
  .drag-ghost {
    position: fixed;
    z-index: 9999;
    pointer-events: none;
    margin: 0;
    box-shadow: 0 20px 45px rgba(32, 50, 100, .22);
    border-color: var(--brand);
    background: #fff;
    opacity: .97;
    transform: rotate(1.2deg) scale(1.015);
    cursor: grabbing;
  }
  body.is-dragging { cursor: grabbing; }
  body.is-dragging .disc-item { cursor: grabbing; }
  .progress-wrap { margin-top: 24px; }
  .progress-meta {
    display: flex; align-items: center; justify-content: space-between;
