<script>
(function () {
  "use strict";

  var HANDLE_SVG = '<svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><circle cx="5" cy="4" r="1.15"/><circle cx="5" cy="8" r="1.15"/><circle cx="5" cy="12" r="1.15"/><circle cx="11" cy="4" r="1.15"/><circle cx="11" cy="8" r="1.15"/><circle cx="11" cy="12" r="1.15"/></svg>';

  var wizard = document.getElementById("rootwizard");
  if (!wizard) return;

  var testView = document.getElementById("testView");
  var resultView = document.getElementById("resultView");
  var tabs = Array.prototype.slice.call(document.querySelectorAll("[data-step-btn]"));
  var panes = Array.prototype.slice.call(document.querySelectorAll("[data-step-pane]"));
  var prevBtn = document.querySelector("[data-disc-prev]");
  var nextBtn = document.querySelector("[data-disc-next]");
  var finishBtn = document.querySelector("[data-disc-finish]");
  var progressEl = document.getElementById("discProgress");
  var progressPercent = document.getElementById("progressPercent");
  var stepLabel = document.getElementById("stepLabel");
  var retakeBtn = document.getElementById("retakeBtn");
  var lists = Array.prototype.slice.call(document.querySelectorAll(".disc-list"));
  var step = 0;
  var TOTAL_STEPS = 8;

  // Decorate static items with the drag handle exactly once.
  lists.forEach(function (ul) {
    Array.prototype.forEach.call(ul.querySelectorAll(".disc-item"), function (li) {
      if (!li.querySelector(".drag-handle")) {
        var text = document.createElement("span");
        text.className = "item-text";
        while (li.firstChild) text.appendChild(li.firstChild);
        var handle = document.createElement("span");
        handle.className = "drag-handle";
        handle.setAttribute("aria-hidden", "true");
        handle.innerHTML = HANDLE_SVG;
        li.appendChild(text);
        li.appendChild(handle);
      }
      li.setAttribute("tabindex", "0");
      li.setAttribute("role", "listitem");
      li.setAttribute("aria-label", li.textContent.trim() + ". Позиция " + (Array.prototype.indexOf.call(ul.children, li) + 1) + " из 4. Стрелки вверх и вниз меняют порядок.");
    });
    ul.setAttribute("role", "list");
  });

  var initialLists = lists.map(function (ul) { return ul.innerHTML; });

  function updateAriaPositions() {
    lists.forEach(function (ul) {
      Array.prototype.forEach.call(ul.children, function (li, i) {
        var textNode = li.querySelector(".item-text");
        var label = (textNode ? textNode.textContent : li.textContent).trim();
        li.setAttribute("aria-label", label + ". Позиция " + (i + 1) + " из " + ul.children.length + ". Стрелки вверх и вниз меняют порядок.");
      });
    });
  }

  function setStep(n) {
    step = Math.max(0, Math.min(TOTAL_STEPS - 1, n));
    tabs.forEach(function (tab, i) {
      var active = i === step;
      tab.classList.toggle("is-active", active);
      tab.setAttribute("aria-selected", active ? "true" : "false");
      tab.setAttribute("tabindex", active ? "0" : "-1");
    });
    panes.forEach(function (pane, i) {
      var active = i === step;
      pane.classList.toggle("is-active", active);
      pane.hidden = !active;
    });
    if (prevBtn) prevBtn.disabled = step === 0;
    if (nextBtn) nextBtn.hidden = step === TOTAL_STEPS - 1;
    if (finishBtn) finishBtn.hidden = step !== TOTAL_STEPS - 1;
    var percent = ((step + 1) / TOTAL_STEPS) * 100;
    if (progressEl) progressEl.style.width = percent + "%";
    if (progressPercent) progressPercent.textContent = Math.round(percent) + "%";
    if (stepLabel) stepLabel.textContent = "Шаг " + (step + 1) + " из " + TOTAL_STEPS;
    var activeTab = tabs[step];
    if (activeTab) activeTab.scrollIntoView({ block: "nearest", inline: "nearest" });
  }

  tabs.forEach(function (tab) {
    tab.addEventListener("click", function () { setStep(Number(tab.dataset.stepBtn)); });
    tab.addEventListener("keydown", function (e) {
      if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
        e.preventDefault();
        var dir = e.key === "ArrowRight" ? 1 : -1;
        var next = (step + dir + TOTAL_STEPS) % TOTAL_STEPS;
        setStep(next);
        tabs[next].focus();
      }
    });
  });
  if (prevBtn) prevBtn.addEventListener("click", function () { setStep(step - 1); });
  if (nextBtn) nextBtn.addEventListener("click", function () { setStep(step + 1); });

  // ---------- drag & drop reordering (mouse, touch, pen) ----------
  var drag = null;

  function beginDrag(e) {
    var li = drag.li;
    var rect = li.getBoundingClientRect();
    var ghost = li.cloneNode(true);
    ghost.classList.remove("is-placeholder");
    ghost.classList.add("drag-ghost");
    ghost.removeAttribute("tabindex");
    ghost.style.width = rect.width + "px";
    ghost.style.height = rect.height + "px";
    ghost.style.left = rect.left + "px";
    ghost.style.top = rect.top + "px";
    document.body.appendChild(ghost);
    li.classList.add("is-placeholder");
    document.body.classList.add("is-dragging");
    drag.ghost = ghost;
    drag.rect = rect;
    drag.dx = e.clientX - rect.left;
    drag.dy = e.clientY - rect.top;
    drag.active = true;
  }

  function moveDrag(e) {
    if (!drag || !drag.active) return;
    var ghost = drag.ghost;
    if (!ghost) return;
    ghost.style.left = (e.clientX - drag.dx) + "px";
    ghost.style.top = (e.clientY - drag.dy) + "px";

    var under = document.elementFromPoint(e.clientX, e.clientY);
    var overLi = under && under.closest ? under.closest(".disc-list > .disc-item") : null;
    if (overLi && overLi.parentElement === drag.list && overLi !== drag.li) {
      var rect = overLi.getBoundingClientRect();
      var before = e.clientY < rect.top + rect.height / 2;
      drag.list.insertBefore(drag.li, before ? overLi : overLi.nextSibling);
    }
  }

  function endDrag() {
    if (!drag) return;
    if (drag.ghost && drag.ghost.parentNode) drag.ghost.parentNode.removeChild(drag.ghost);
    if (drag.li) drag.li.classList.remove("is-placeholder");
    document.body.classList.remove("is-dragging");
    if (drag.active) updateAriaPositions();
    drag = null;
  }

  wizard.addEventListener("pointerdown", function (e) {
    if (e.button != null && e.button !== 0) return;
    var li = e.target.closest ? e.target.closest(".disc-list > .disc-item") : null;
    if (!li || !wizard.contains(li)) return;
    // On touch, only the visible handle starts a drag; elsewhere the page can scroll.
    if (e.pointerType === "touch" || e.pointerType === "pen") {
      if (!e.target.closest(".drag-handle")) return;
    }
    drag = {
      li: li,
      list: li.parentElement,
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      active: false,
      ghost: null
    };
  });

  document.addEventListener("pointermove", function (e) {
    if (!drag || (drag.pointerId != null && e.pointerId !== drag.pointerId)) return;
    if (!drag.active) {
      var distance = Math.hypot(e.clientX - drag.startX, e.clientY - drag.startY);
      if (distance < 6) return;
      beginDrag(e);
    }
    if (e.cancelable) e.preventDefault();
    moveDrag(e);
  }, { passive: false });

  document.addEventListener("pointerup", endDrag);
  document.addEventListener("pointercancel", endDrag);
  window.addEventListener("blur", endDrag);

  // Keyboard reordering keeps the lists usable without a pointer.
  wizard.addEventListener("keydown", function (e) {
    var li = e.target.closest ? e.target.closest(".disc-list > .disc-item") : null;
    if (!li) return;
    if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
    e.preventDefault();
    var list = li.parentElement;
    if (e.key === "ArrowUp" && li.previousElementSibling) {
      list.insertBefore(li, li.previousElementSibling);
    } else if (e.key === "ArrowDown" && li.nextElementSibling) {
      list.insertBefore(li.nextElementSibling, li);
    } else {
      return;
    }
    updateAriaPositions();
    li.focus({ preventScroll: true });
  });

  // ---------- scoring ----------
  function computeScore() {
    var score = { d: 0, i: 0, s: 0, c: 0 };
    lists.forEach(function (ul) {
      var items = Array.prototype.slice.call(ul.querySelectorAll(".disc-item"));
      if (items.length !== 4) return;
      var firstType = items[0].getAttribute("data-type");
      var lastType = items[items.length - 1].getAttribute("data-type");
      if (score.hasOwnProperty(firstType)) score[firstType] += 1;
      if (score.hasOwnProperty(lastType)) score[lastType] -= 1;
    });
    return score;
  }

  function showResult() {
    var score = computeScore();
    document.getElementById("scoreD").textContent = score.d;
    document.getElementById("scoreI").textContent = score.i;
    document.getElementById("scoreS").textContent = score.s;
    document.getElementById("scoreC").textContent = score.c;
    document.getElementById("cardD").textContent = score.d;
    document.getElementById("cardI").textContent = score.i;
    document.getElementById("cardS").textContent = score.s;
    document.getElementById("cardC").textContent = score.c;
    testView.hidden = true;
    resultView.hidden = false;
    window.scrollTo({ top: 0, behavior: "smooth" });
    var heading = resultView.querySelector("h2");
    if (heading) {
      heading.setAttribute("tabindex", "-1");
      heading.focus({ preventScroll: true });
    }
  }

  if (finishBtn) finishBtn.addEventListener("click", showResult);

  if (retakeBtn) {
    retakeBtn.addEventListener("click", function () {
      lists.forEach(function (ul, i) { ul.innerHTML = initialLists[i]; });
      updateAriaPositions();
      resultView.hidden = true;
      testView.hidden = false;
      setStep(0);
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }

  setStep(0);
})();
